import ldap from "ldapjs";
//import client from "../../config/ldapconfig.js";
import config from "../../config/envConfig.js";
import sequelize from "../../config/dbConfig.js";
import { QueryTypes } from "sequelize";

function escapeLDAP(value) {
  return value.replace(/[\*\(\)\\\0\/]/g, (char) => {
    switch (char) {
      case "*":
        return "\\2a";
      case "(":
        return "\\28";
      case ")":
        return "\\29";
      case "\\":
        return "\\5c";
      case "\0":
        return "\\00";
      case "/":
        return "\\2f";
      default:
        return char;
    }
  });
}

/**
 * Fetch all groups from LDAP
 * @returns {Promise<Array>} Array of LDAP groups
 */
export function getAllLdapGroups(callback) {
  const ldapUrl = config.LDAP_URL;
  const username = config.LDAP_BIND_USERNAME;
  const adminDn = `${username}@${config.LDAP_BIND_DN}`;
  // const adminDn = "cn=appdeveloper,dc=hnhriyadh,dc=com"; // Replace with your AD admin DN
  const password = "123"; // Replace with the correct password

  const client = ldap.createClient({
    url: ldapUrl,
    reconnect: true,
    timeout: 5000,
    connectTimeout: 10000,
  });

  client.bind(adminDn, password, (err) => {
    if (err) {
      console.error("LDAP bind error:", err);
      return callback("LDAP bind error: " + err.message, null);
    }

    const options = {
      filter: "(objectClass=group)",
      scope: "sub",
      attributes: ["cn", "distinguishedName"],
      paged: true, // Important for large directories
    };

    const groups = [];

    client.search("DC=hnhriyadh,DC=com", options, (err, res) => {
      if (err) {
        console.error("LDAP search error:", err);
        client.unbind(() => callback("LDAP search error: " + err.message, null));
        return;
      }

      res.on("searchEntry", (entry) => {
        try {
          if (entry.pojo && entry.pojo.attributes) {
            const cnAttr = entry.pojo.attributes.find((attr) => attr.type === "cn");
            if (cnAttr && cnAttr.values && cnAttr.values[0]) {
              groups.push(cnAttr.values[0]);
            }
          }
        } catch (e) {
          console.warn("Error processing entry:", e);
        }
      });

      res.on("error", (err) => {
        console.error("Search error:", err);
        client.unbind(() => callback("Search error: " + err.message, null));
      });

      res.on("end", (result) => {
        if (result && result.status !== 0) {
          console.error("Search ended with status:", result.status);
        }
        client.unbind(() => callback(null, groups));
      });
    });
  });
}

export function getAllLdapGroupsWithDESC(callback) {
  console.log("config.LDAP_BIND_DN: " + config.LDAP_BIND_DN);
  if (!config.LDAP_URL || !config.LDAP_BIND_USERNAME || !config.LDAP_BIND_DN || !config.LDAP_BIND_PASSWORD) {
    const error = new Error("Missing LDAP configuration in environment variables");
    console.error(error.message);
    return callback(error.message, null);
  }

  const ldapUrl = config.LDAP_URL;
  const username = config.LDAP_BIND_USERNAME;
  const adminDn = `${username}@${config.LDAP_BIND_DN}`;
  const password = config.LDAP_BIND_PASSWORD;

  const client = ldap.createClient({
    url: ldapUrl,
    reconnect: true,
    timeout: 5000,
    connectTimeout: 10000,
  });

  client.bind(adminDn, password, (err) => {
    if (err) {
      console.error("LDAP bind error:", err);
      return callback("LDAP bind error: " + err.message, null);
    }

    const options = {
      filter: "(objectClass=group)",
      scope: "sub",
      attributes: ["cn", "distinguishedName", "description"],
      paged: true,
    };

    const groups = [];

    client.search(config.LDAP_GROUP_SEARCH_BASE || config.LDAP_SEARCH_BASE, options, (err, res) => {
      if (err) {
        console.error("LDAP search error:", err);
        client.unbind(() => callback("LDAP search error: " + err.message, null));
        return;
      }

      res.on("searchEntry", (entry) => {
        try {
          if (entry.pojo && entry.pojo.attributes) {
            const cnAttr = entry.pojo.attributes.find((attr) => attr.type === "cn");
            const descAttr = entry.pojo.attributes.find((attr) => attr.type === "description");
            if (cnAttr && cnAttr.values && cnAttr.values[0]) {
              groups.push({ name: cnAttr.values[0], description: descAttr?.values?.[0] || "" });
            }
          }
        } catch (e) {
          console.warn("Error processing entry:", e);
        }
      });

      res.on("error", (err) => {
        console.error("Search error:", err);
        client.unbind(() => callback("Search error: " + err.message, null));
      });

      res.on("end", (result) => {
        if (result && result.status !== 0) {
          console.error("Search ended with status:", result.status);
        }
        client.unbind(() => callback(null, groups));
      });
    });
  });
}

export function getGroupMembers(groupName, callback) {
  const ldapUrl = config.LDAP_URL;
  const username = config.LDAP_BIND_USERNAME;
  const adminDn = `${username}@${config.LDAP_BIND_DN}`;
  const password = config.LDAP_BIND_PASSWORD;

  const client = ldap.createClient({
    url: ldapUrl,
    reconnect: true,
    timeout: 5000,
    connectTimeout: 10000,
  });

  client.bind(adminDn, password, (err) => {
    if (err) {
      console.error("LDAP bind error:", err);
      return callback("LDAP bind error: " + err.message, null);
    }

    const options = {
      filter: `(cn=${escapeLDAP(groupName)})`,
      scope: "sub",
      attributes: ["member"],
      paged: true,
    };

    client.search(config.LDAP_GROUP_SEARCH_BASE || config.LDAP_SEARCH_BASE, options, (err, res) => {
      if (err) {
        console.error("LDAP search error:", err);
        client.unbind(() => callback("LDAP search error: " + err.message, null));
        return;
      }

      const members = [];

      res.on("searchEntry", (entry) => {
        try {
          const memberAttr = entry.pojo?.attributes?.find((attr) => attr.type === "member");
          if (memberAttr?.values) {
            members.push(...memberAttr.values);
          }
        } catch (e) {
          console.warn("Error processing entry:", e);
        }
      });

      res.on("error", (err) => {
        console.error("Search error:", err);
        client.unbind(() => callback("Search error: " + err.message, null));
      });

      res.on("end", (result) => {
        if (result && result.status !== 0) {
          console.error("Search ended with status:", result.status);
        }
        client.unbind(() => callback(null, members));
      });
    });
  });
}

export async function syncGroupsAndMembers(groups) {
  const ldapUrl = config.LDAP_URL;
  const username = config.LDAP_BIND_USERNAME;
  const adminDn = `${username}@${config.LDAP_BIND_DN}`;
  const password = config.LDAP_BIND_PASSWORD;

  // Define user search base using config or fallback
  const userSearchBase = config.LDAP_SEARCH_BASE || "DC=hnhriyadh,DC=com";

  const client = ldap.createClient({
    url: ldapUrl,
    reconnect: true,
    timeout: 5000,
    connectTimeout: 10000,
  });

  // Extract group names for SQL IN clause
  const groupNames = groups.map((g) => g.name);

  try {
    // Step 1: Get existing group IDs for provided group names
    const existingGroupsQuery = `
      SELECT group_id, group_name
      FROM app_group
      WHERE group_name = ANY($1)
    `;

    const existingGroups = await sequelize.query(existingGroupsQuery, { bind: [groupNames], type: QueryTypes.SELECT });

    // Step 2: Insert missing groups and capture their IDs
    const groupsToInsert = groups.filter((g) => !existingGroups.some((eg) => eg.group_name === g.name));

    let newGroupIds = [];
    if (groupsToInsert.length > 0) {
      await sequelize.transaction(async (t) => {
        // Use ON CONFLICT to avoid errors if group already exists
        const insertQuery = `
          INSERT INTO app_group (group_name)
          VALUES ($1)
          ON CONFLICT (group_name) DO NOTHING
          RETURNING group_id
        `;

        for (const group of groupsToInsert) {
          const inserted = await sequelize.query(insertQuery, {
            bind: [group.name],
            type: QueryTypes.SELECT,
            transaction: t,
          });
          if (inserted.length > 0) {
            newGroupIds.push(inserted[0].group_id);
          }
        }
      });
    }

    // Combine existing and newly created group IDs
    const allGroupsQuery = `
      SELECT group_id, group_name
      FROM app_group
      WHERE group_name = ANY($1)
    `;

    const allGroups = await sequelize.query(allGroupsQuery, { bind: [groupNames], type: QueryTypes.SELECT });

    // Step 3: Bind to LDAP
    await new Promise((resolve, reject) => {
      client.bind(adminDn, password, (err) => {
        if (err) {
          console.error("LDAP bind error:", err);
          return reject(new Error("LDAP bind error: " + err.message));
        }
        resolve();
      });
    });

    // Step 4: For each group, search members and update database
    for (const group of groups) {
      await new Promise((resolve, reject) => {
        const escapedGroupName = escapeLDAP(group.name);
        const searchOptions = {
          scope: "sub",
          filter: `(&(objectClass=group)(cn=${escapedGroupName}))`,
          attributes: ["member"],
          paged: true,
        };

        client.search(config.LDAP_GROUP_SEARCH_BASE || config.LDAP_SEARCH_BASE, searchOptions, (err, res) => {
          if (err) {
            console.error("LDAP search error for group:", group.name, err);
            return reject(new Error("LDAP search error: " + err.message));
          }

          let members = [];

          res.on("searchEntry", (entry) => {
            const memberAttr = entry.pojo?.attributes?.find((attr) => attr.type === "member");
            if (memberAttr?.values) {
              members = memberAttr.values;
            }
          });

          res.on("error", (err) => {
            console.error("Search error:", err);
            reject(new Error("Search error: " + err.message));
          });

          res.on("end", async () => {
            try {
              if (members.length === 0) return resolve();

              const ldapUsers = members.map((dn) => {
                const cnMatch = dn.match(/CN=([^,]+)/);
                const ouMatch = dn.match(/OU=([^,]+)/);
                return {
                  user_name: cnMatch ? cnMatch[1] : null,
                  group_name: ouMatch ? ouMatch[1] : group.name,
                };
              });

              // Map LDAP users to DB structure
              const usersToInsert = ldapUsers
                .filter((u) => u.user_name)
                .map((u) => ({ user_name: u.user_name, group_name: u.group_name }));

              // Fetch group IDs only once
              const groupNamesSet = [...new Set(usersToInsert.map((u) => u.group_name))];
              const groupIdsQuery = `
                SELECT group_id, group_name
                FROM app_group
                WHERE group_name = ANY($1)
              `;
              const groupIds = await sequelize.query(groupIdsQuery, { bind: [groupNamesSet], type: QueryTypes.SELECT });
              const groupIdMap = Object.fromEntries(groupIds.map((g) => [g.group_name, g.group_id]));

              // Filter out users without a valid group ID
              const validUsers = usersToInsert
                .map((u) => ({ user_name: u.user_name, group_id: groupIdMap[u.group_name] }))
                .filter((u) => u.group_id);

              if (validUsers.length === 0) return resolve();

              // Insert users without duplicates
              const insertUsersQuery = `
                INSERT INTO "user" (user_name, active, locked, creation_date)
                VALUES ($1, 'Y', 'N', NOW())
                ON CONFLICT (user_name) DO NOTHING
                RETURNING user_id
              `;

              for (const user of validUsers) {
                await sequelize.query(insertUsersQuery, { bind: [user.user_name], type: QueryTypes.SELECT });
              }

              // Link users to groups without duplicates
              const linkUserGroupQuery = `
                INSERT INTO user_group (user_id, group_id, creation_date)
                SELECT u.user_id, $1, NOW()
                FROM "user" u
                WHERE u.user_name = $2
                ON CONFLICT (user_id, group_id) DO NOTHING
              `;

              for (const user of validUsers) {
                await sequelize.query(linkUserGroupQuery, { bind: [user.group_id, user.user_name], type: QueryTypes.INSERT });
              }

              resolve();
            } catch (error) {
              console.error("Database operation error:", error);
              reject(new Error("Failed to update database: " + error.message));
            }
          });
        });
      });
    }

    client.unbind();
    console.log("Groups and users synchronized successfully.");
  } catch (error) {
    console.error("Failed to sync groups and members:", error);
    throw error;
  }
}
